CREATE TABLE users (id INT AUTO_INCREMENT PRIMARY KEY, openId VARCHAR(64) UNIQUE NOT NULL, name VARCHAR(160), email VARCHAR(320), role ENUM('user','admin') NOT NULL DEFAULT 'user', createdAt TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE categories (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(80) UNIQUE NOT NULL, slug VARCHAR(100) UNIQUE NOT NULL, isActive BOOLEAN DEFAULT TRUE, createdAt TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE products (id INT AUTO_INCREMENT PRIMARY KEY, categoryId INT NULL, name VARCHAR(180) NOT NULL, slug VARCHAR(220) UNIQUE NOT NULL, brand VARCHAR(100) NOT NULL, style VARCHAR(100) NOT NULL, material VARCHAR(100) NOT NULL, color VARCHAR(60) NOT NULL, description TEXT, regularPrice DECIMAL(10,2) NOT NULL, salePrice DECIMAL(10,2), isFeatured BOOLEAN DEFAULT FALSE, isOnSale BOOLEAN DEFAULT FALSE, isNew BOOLEAN DEFAULT FALSE, isActive BOOLEAN DEFAULT TRUE, createdAt TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updatedAt TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY (categoryId) REFERENCES categories(id) ON DELETE SET NULL);
CREATE TABLE productImages (id INT AUTO_INCREMENT PRIMARY KEY, productId INT NOT NULL, url TEXT NOT NULL, storageKey VARCHAR(255), alt VARCHAR(180), sortOrder INT DEFAULT 0, isCover BOOLEAN DEFAULT FALSE, FOREIGN KEY (productId) REFERENCES products(id) ON DELETE CASCADE);
CREATE TABLE productVariants (id INT AUTO_INCREMENT PRIMARY KEY, productId INT NOT NULL, size VARCHAR(12) NOT NULL, stock INT DEFAULT 0, sku VARCHAR(80) UNIQUE NOT NULL, FOREIGN KEY (productId) REFERENCES products(id) ON DELETE CASCADE);
CREATE TABLE inquiries (id INT AUTO_INCREMENT PRIMARY KEY, productId INT NOT NULL, customerName VARCHAR(120) NOT NULL, customerPhone VARCHAR(40) NOT NULL, message TEXT, status ENUM('new','contacted','closed') DEFAULT 'new', createdAt TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (productId) REFERENCES products(id) ON DELETE CASCADE);
